('2','Asymmetric Olive Drape Set',320,array['/products/image-2.webp']::text[],'Sets','DAIRI Edit','An olive set built around soft asymmetry, balancing a sculptural drape with everyday comfort.',array[]::text[],'published',true,'2026-01-01','Olive','#5a6b3a',array['Asymmetric neckline','Fluid matching trouser','Soft waist definition']::text[],'Matte crepe with gentle stretch','Draped top with relaxed full-length trousers','Hand wash cold or dry clean',array['XS','S','M','L']::text[]),
