('4','Classic Striped Tunic',195,array['/products/image-4.webp']::text[],'Tops','DAIRI Edit','A polished striped tunic with a clean vertical line, designed to layer easily over trousers or slim skirts.',array['bestseller']::text[],'published',true,'2026-01-01','Burgundy','#7a1a1f',array['Longline cut','Side vents','Graphic stripe layout']::text[],'Cotton-viscose shirting','Straight, easy fit','Machine wash cold, hang dry',array['XS','S','M','L','XL']::text[]),
('5','Teal Print Kaftan Dress',265,array['/products/image-2.webp']::text[],'Dresses','DAIRI Edit','A relaxed kaftan dress in saturated teal, finished with an expressive print and airy volume.',array['new']::text[],'published',true,'2026-01-01','Teal','#177a7a',array['Kaftan silhouette','Wide sleeve opening','Soft side slits']::text[],'Printed viscose voile','Generous relaxed fit','Hand wash cold, reshape while damp',array['S','M','L','XL']::text[]),
('6','Teal Fluid Cowl Set',340,array['/products/image-3.webp']::text[],'Sets','DAIRI Edit','A fluid teal set with a soft cowl neckline and wide-leg trouser, made for elegant movement.',array[]::text[],'published',true,'2026-01-01','Teal','#177a7a',array['Cowl neckline','Wide-leg trouser','Soft elastic waist']::text[],'Silky jersey crepe','Relaxed and fluid','Dry clean or gentle cold wash',array['XS','S','M','L']::text[]),
