('8','Chenille Cape with Scarf',210,array['/products/image-1.webp']::text[],'Tops','DAIRI Edit','A burgundy chenille cape with an integrated scarf, designed as a soft finishing layer.',array[]::text[],'published',true,'2026-01-01','Burgundy','#7a1a1f',array['Cape body','Integrated scarf panel','Open front']::text[],'Plush chenille knit','One-size relaxed drape','Dry clean recommended',array['OS']::text[]),
