-- Local seed catalogue for the DAIRI storefront (prices in USD).
on conflict (id) do update set name=excluded.name,price=excluded.price,images=excluded.images,category=excluded.category,collection=excluded.collection,description=excluded.description,tags=excluded.tags,status=excluded.status,show_on_website=excluded.show_on_website,color=excluded.color,color_hex=excluded.color_hex,details=excluded.details,material=excluded.material,fit=excluded.fit,care=excluded.care,sizes=excluded.sizes,updated_at=now();

-- Clearly marked local demo identifiers and stock so checkout can be exercised.
update public.products set style_number = 'DEMO-' || upper(id) where id ~ '^[0-9]+$' and id::integer between 1 and 11;
select p.id,
       upper('DEMO-' || p.id || '-' || regexp_replace(coalesce(nullif(p.color, ''), 'STANDARD') || '-' || coalesce(nullif(s.size, ''), 'ONE-SIZE'), '[^A-Za-z0-9-]+', '-', 'g')),
       coalesce(p.color, ''), p.color_hex, coalesce(s.size, ''), 10
from public.products p
cross join lateral (select distinct unnest(coalesce(p.sizes, array[''])) as size) s
where p.id ~ '^[0-9]+$' and p.id::integer between 1 and 11
on conflict (product_id, color, size) do update set sku=excluded.sku, color_hex=excluded.color_hex, inventory_quantity=10, is_active=true, updated_at=now();


on conflict (id) do nothing;

values ('default','DAIRI','','#000000','#f5f5f5','inter','a4','editorial','','Creative Director','USD')
on conflict (id) do update set brand_name=excluded.brand_name, primary_color=excluded.primary_color, secondary_color=excluded.secondary_color, font_family=excluded.font_family, default_format=excluded.default_format, default_layout=excluded.default_layout, email=excluded.email, name=excluded.name, currency=excluded.currency;
